INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33759$nota-0248$m33759$, $m33760$Exercise Physiology McArdle.pdf$m33760$, $m33761$513$m33761$, $m33762$Table 22.2 Summary of Resistance Training Recommendations: an Overview of Different Program Variables Needed for Progression with Different Fitness Levels. Strength — Nov.: 60–70% of 1RM, 1–3 sets, 8–12 reps, 2–3 min rest; Int.: 70–80% of 1RM, mult. sets 6–12 reps; Adv.: 1RM—PER, mult. sets 1–12 reps—PER. Power — Nov.: Heavy loads (>80%)—strength; Light (30–60%)—velocity—PER, train for strength; Int./Adv.: 1–3 sets 3–6 reps up to 3–6 sets 1–6 reps—PER. Endurance — Nov.: 50–70% of 1RM, 1–3 sets 10–15 reps; Adv.: 30–80% of 1RM—PER, mult. sets 10–25 reps or more—PER. From ACSM position stand on: Progression models in resistance training for healthy adults. Med Sci Sports Exerc 2002;34:364.$m33762$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33763$nota-0248$m33763$, $m33764$Exercise Physiology McArdle.pdf$m33764$, $m33765$511$m33765$, $m33766$1. Eight- to 12-RM proves effective in novice training, whereas 1- to 12-RM effectively loads for intermediate training. This can then increase to more intense loading using 1- to 6-RM. 2. Rest 3 min between sets of an exercise at moderate movement velocity... 13. Power training should apply the strategy to improve muscular strength plus include lighter loads (30 to 60% of 1-RM) performed at fast contraction velocity.$m33766$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33767$nota-0248$m33767$, $m33768$nota-0187$m33768$, $m33769$complementa$m33769$, $m33770$nota-0187 estabelece que o foco do treino de força para ciclistas é neuromuscular, não hipertrofia máxima; esta nota fornece os parâmetros numéricos (séries/reps/%1RM) do protocolo ACSM que operacionalizam esse foco (colunas Força e Potência, não Hipertrofia)$m33770$)
ON CONFLICT DO NOTHING;
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m33771$nota-0248$m33771$, $m33772$nota-0069$m33772$, $m33773$complementa$m33773$, $m33774$nota-0069 mostra que treino de força-resistência (altas repetições) não aumenta força máxima; a coluna 'Endurance' desta tabela (30-70% 1RM, 10-25+ reps) é o protocolo correspondente a esse objetivo, em contraste com as colunas Força/Potência$m33774$)
ON CONFLICT DO NOTHING;
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33775$nota-0250$m33775$, $m33776$Exercise Physiology McArdle.pdf$m33776$, $m33777$574$m33777$, $m33778$Warm-up performed at moderate- and high-intensity improved intense cycling performance by 2 to 3%. A pre-exercise warm-up irrespective of intensity enhanced a 3- to 4-min (3-km) cycling time trial. This effect likely resulted from an acceleration of oxygen uptake kinetics from augmented blood flow at exercise onset. An active warm-up 5 min prior to a 30-s maximal sprint on a bicycle ergometer produced less blood and muscle lactate than equivalent effort without a physical warm-up.$m33778$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m33779$nota-0250$m33779$, $m33780$Exercise Physiology McArdle.pdf$m33780$, $m33781$574$m33781$, $m33782$Five mechanisms explain why warm-up 'should' improve physical performance and exercise capacity because of subsequent increases in blood flow and muscle and core temperature: 1. Faster muscle contraction and relaxation 2. Greater economy of movement from lowered viscous resistance within active muscles 3. Facilitated oxygen delivery and use by muscles because hemoglobin releases oxygen more readily at higher temperatures (Bohr effect) 4. Facilitated nerve transmission and muscle metabolism [...] 5. Increased blood flow through active tissues...$m33782$);
COMMIT;